from typing import List
import heapq

class Solution:
    def minCost(self, maxTime: int, edges: List[List[int]], passingFees: List[int]) -> int:
        n = len(passingFees)
        graph = [[] for _ in range(n)]
        for u,v,w in edges:
            graph[u].append((w,v))
            graph[v].append((w,u))

        heap = [(passingFees[0],0,0)]
        time = [float('inf')]*n
        time[0] = 0
        while heap:
            fee,p_time, parent = heapq.heappop(heap)
            for c_time, child in graph[parent]:
                new_time = p_time + c_time
                new_fees = fee + passingFees[child]
                if new_time > maxTime or new_time >= time[child]:
                    continue
                if child == n-1:
                    return new_fees
                time[child] = new_time
                heapq.heappush(heap, (new_fees,new_time,child))
        return -1



